-- Production hardening: declare the foreign keys that were only implied by
-- column names, add the indexes lists filter on, and add CHECK constraints
-- for rules the API now enforces (so other writers can't break them either).
--
-- The CreateIndex / AddForeignKey part is generated by `prisma migrate diff`;
-- the data clean-up before it and the CHECK constraints after it are
-- hand-written.

-- Data, before the foreign keys can be added: these columns were never
-- checked, so a value may point at nothing or at another company's row.
-- Such a value never meant anything to the app (nothing reads it as a
-- reference); it is cleared.
UPDATE "Employee" AS e SET "managerId" = NULL
WHERE e."managerId" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "Employee" AS m WHERE m."id" = e."managerId" AND m."companyId" = e."companyId");
UPDATE "Department" AS d SET "managerId" = NULL
WHERE d."managerId" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "Employee" AS m WHERE m."id" = d."managerId" AND m."companyId" = d."companyId");
UPDATE "ApiKey" AS k SET "createdById" = NULL
WHERE k."createdById" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "User" AS u WHERE u."id" = k."createdById" AND u."companyId" = k."companyId");
UPDATE "StoredFile" AS f SET "uploadedById" = NULL
WHERE f."uploadedById" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "User" AS u WHERE u."id" = f."uploadedById" AND u."companyId" = f."companyId");

-- CreateIndex
CREATE INDEX "ApiKey_createdById_idx" ON "ApiKey"("createdById");

