-- AddForeignKey
ALTER TABLE "Department" ADD CONSTRAINT "Department_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ApiKey" ADD CONSTRAINT "ApiKey_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StoredFile" ADD CONSTRAINT "StoredFile_uploadedById_fkey" FOREIGN KEY ("uploadedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- CHECK constraints. Prisma's schema language has no CHECK, so they live
-- here (like the inventory ones). NOT VALID: enforced for every new or
-- changed row, without failing this migration on rows saved before the
-- rule existed (e.g. a leave request stored with reversed dates); such a
-- row must be corrected the next time it is edited.
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_dates_in_order"
  CHECK ("endDate" >= "startDate") NOT VALID;
ALTER TABLE "EmploymentContract" ADD CONSTRAINT "EmploymentContract_dates_in_order"
  CHECK ("endDate" IS NULL OR "endDate" >= "startDate") NOT VALID;
ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_period_in_order"
  CHECK ("toDate" >= "fromDate") NOT VALID;
ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_vatPercent_range"
  CHECK ("vatPercent" >= 0 AND "vatPercent" <= 100) NOT VALID;
ALTER TABLE "InvoiceLineItem" ADD CONSTRAINT "InvoiceLineItem_taxPercent_range"
  CHECK ("taxPercent" >= 0 AND "taxPercent" <= 100) NOT VALID;
